//! ⚡️ Shooting artifact — OpText/OpBinary codecs for `ShootingMutation`. Mutation apply/inverse
//! (via `protocol::Mutation`/`protocol::SemanticMutation`, generated by
//! `#[derive(dsl_derive::Mutations)]` on the dispatch enum in `../../../🧬️schema/🧬️mutations/🦀️.rs`) is NOT this
//! file's concern; this file only wires the operation-log line/binary encodings.
//!
//! Every `ShootingMutation` variant wraps a plain local payload struct now (no foreign generic —
//! the pre-migration generic-option-bag-flattening `ShootingMutationDsl` mirror this file used
//! to carry, needed only to route around the orphan rule, is gone with it). `dsl::os_pack::json`'s
//! compact (single-line, declaration-order) encoding satisfies `OpText`/`OpBinary`'s laws directly:
//! `print_op` never contains `\n`, `parse_op(op.print_op()) == op`, and encoding is deterministic —
//! no `serde_json` anywhere in this leaf.

use crate::standards::v1::subsets::any::schema::mutations::ShootingMutation;

//#region 📖️SemioGrammar
/// 📖️ Normative handcrafted text grammar for this facet (`dialect grammar`).
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️.grammar.semio");
//#endregion 📖️SemioGrammar

//#region 🔖️OpText
impl protocol::OpText for ShootingMutation {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        semio_framework_pack_json::from_json_str(line, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| semio_framework_diagnostic::TextError::from_value_error(error.under("shooting mutation line"), semio_framework_diagnostic::TextSpan::at(1, 1)))
    }
    fn print_op(&self) -> String {
        semio_framework_pack_json::to_json_string(self)
    }
}
//#endregion 🔖️OpText

//#region 🔖️OpBinary
//#region 🏷️WireTags
/// 🏷️ `ShootingMutation`'s wire protocol: its `record <kind> tag=<n>` lines are the only source of the op tags.
const WIRE_PROTOCOL: &str = include_str!("../../💾️binary/🧬️mutations/📡️.protocol.semio");
//#endregion 🏷️WireTags

impl protocol::OpBinary for ShootingMutation {
    fn encode_op(&self) -> Result<Vec<u8>, protocol::ProtocolError> {
        dsl::tagged_value_binary::encode_op(WIRE_PROTOCOL, dsl::tagged_value_binary::VariantTag::Field("mutation"), self)
    }
    fn decode_op(bytes: &[u8]) -> Result<Self, protocol::ProtocolError> {
        dsl::tagged_value_binary::decode_op(WIRE_PROTOCOL, dsl::tagged_value_binary::VariantTag::Field("mutation"), bytes)
    }
}
//#endregion 🔖️OpBinary

#[allow(unused_imports)]
mod mutations_codec {
use super::*;
use crate::standards::v1::subsets::any::schema::mutations::*;
use crate::diff::ShootingDiff;
use crate::ShootingSnapshot;

/// 📥️ Decodes this facet's own internally-tagged (`{"mutation": "createAsset", …}`) JSON projection
/// — the shape the `🎥️mutate-shooting-1` case's `Examples` rows carry, and the shape every committed
/// per-kind leaf fixture under `<kind>/🧪️tests/*/🦠️mutation/🔣️.json` already is — into a real
/// [`ShootingMutation`], via this crate's own `dsl::os_pack::json` parser/bridge (no `serde_json`).
pub fn decode_shooting_mutation_json(text: &str) -> Result<ShootingMutation, String> {
    let json_value = semio_framework_pack_json::parse(text, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| error.to_string())?;
    let dsl_value = semio_framework_pack_json::to_dsl_value(&json_value);
    semio_framework_value::FromValue::from_value(dsl_value).map_err(|error| error.to_string())
}

/// ⚖️ The SEMANTIC PROJECTION this subset is compared through. It belongs to the subset rather than
/// to a test adapter, because what counts as this document's meaning is this subset's ruling, not a
/// case's. Every inline artifact-lane field is present; the composed `emblem` child handle is not,
/// because it is a content address for an `s.stdio.semio.image` child that no kind of this
/// vocabulary addresses.
pub fn encode_shooting_projection_json(snapshot: &ShootingSnapshot) -> String {
    let assets = semio_framework_pack_json::from_dsl_value(&semio_framework_value::ToValue::to_value(&snapshot.assets));
    let saved_cameras = semio_framework_pack_json::from_dsl_value(&semio_framework_value::ToValue::to_value(&snapshot.saved_cameras));
    let scene = semio_framework_pack_json::from_dsl_value(&semio_framework_value::ToValue::to_value(&snapshot.scene));
    let shots = semio_framework_pack_json::from_dsl_value(&semio_framework_value::ToValue::to_value(&snapshot.shots));
    semio_framework_pack_json::json!({
        "schema": snapshot.schema.as_str(),
        "assets": assets,
        "savedCameras": saved_cameras,
        "scene": scene,
        "shots": shots,
        "activeShotId": snapshot.active_shot_id.as_str(),
        "activeAssetId": snapshot.active_asset_id.as_str()
    })
    .to_string()
}
}
pub use mutations_codec::*;

/// 📜️ Describes the artifact mutation dialect.
pub const MUTATION_GRAMMAR_SEMIO: &str = include_str!("📖️mutations.grammar.semio");
/// 🧭️ Identifies the artifact mutation grammar.
pub const MUTATION_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️mutations.grammar.semio");
